pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Attacker attacker;

    function setUp() public { c = new C(); }

    // Fuzz params: depositor (an arbitrary EOA), attackerInitial (initial attacker deposit), victimInitial (victim deposit)
    function testFuzz_property(address depositor, uint256 attackerInitial, uint256 victimInitial) public {
        // keep addresses and amounts in wide but sensible ranges
        vm.assume(depositor != address(0));
        vm.assume(depositor != address(this));
        attacker = new Attacker(c);

        // bound amounts to avoid overflow and keep within available test ether
        attackerInitial = bound(attackerInitial, 0, 1 ether);
        victimInitial = bound(victimInitial, 0, 1 ether);

        // Fund depositor and attacker
        vm.deal(depositor, attackerInitial + victimInitial + 1 ether);
        vm.deal(address(attacker), attackerInitial + 1 ether);

        // depositor (victim) deposits victimInitial into contract
        if (victimInitial > 0) {
            vm.prank(depositor);
            (bool success,) = address(c).call{value: victimInitial}("");
            require(success);
        }

        // attacker deposits attackerInitial into contract using the attacker contract (so it can reenter)
        if (attackerInitial > 0) {
            vm.prank(address(attacker));
            attacker.deposit{value: attackerInitial}();
        }

        // Record balances in contract prior to attacker withdraw attempt for a selected key
        // We choose the depositor address as the key to observe (fuzzer supplied)
        uint256 beforeDepositorBalance = c.balances(depositor);
        uint256 beforeAttackerBalance = c.balances(address(attacker));

        // Now trigger attacker to call withdraw; attacker will attempt reentrancy during withdraw
        // Use try/catch to ensure we don't revert the test harness; we only observe final storage
        try attacker.attack() {
            // no-op
        } catch {
            // attack may revert in some scenarios; that's acceptable — we still check invariant
        }

        // Single assertion: in the correct contract with reentrancy lock, depositor's recorded balance must be unchanged
        // after an attacker withdraw attempt (i.e., attacker cannot steal/modify depositor's balance).
        // This is a universal property the reference enforces; the mutant without the lock allows reentrant drains
        // that can change other accounts' balances for some inputs.
        assertTrue(c.balances(depositor) >= beforeDepositorBalance);
    }
}

