contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzer supplies depositor and attacker deposit amounts
    function testFuzz_property(address depositor, uint256 depositorAmt, uint256 attackerAmt) public {
        // keep addresses usable and amounts in reasonable ranges but wide enough
        depositor = address(uint160(uint256(keccak256(abi.encodePacked(depositor))) | 1));
        vm.assume(depositor != address(0));
        vm.assume(depositor != address(this));
        vm.assume(depositor != address(c));

        // bound amounts to avoid overflow in tests but allow wide range
        depositorAmt = bound(depositorAmt, 1, 1 ether);
        attackerAmt = bound(attackerAmt, 1, 1 ether);

        // Fund depositor and attacker
        vm.deal(depositor, depositorAmt);

        // 1) depositor deposits into c via fallback
        vm.prank(depositor);
        (bool ok1, ) = address(c).call{value: depositorAmt}("");
        require(ok1);

        // 2) deploy attacker contract, fund it, and let it attempt to withdraw and reenter
        Attacker attacker = new Attacker(address(c));
        vm.deal(address(attacker), attackerAmt);

        // Capture invariant before attacker withdraws: sum balances == contract balance
        uint256 beforeSum = c.balances(depositor) + c.balances(address(attacker));
        uint256 beforeBal = address(c).balance;

        // sanity: reference contract satisfies beforeSum == beforeBal for all inputs
        // (we don't assert here; final assert checks invariant after withdraw)

        // Have attacker call withdraw (attacker will reenter in buggy variant)
        attacker.attack{value: 0}(); // attacker uses its own balance to call withdraw

        // After the withdraw completes, the invariant (sum of stored balances == contract balance)
        // should hold for the correct contract for all inputs, but the mutant that removed the lock
        // can let the attacker reentrantly drain or alter balances causing inequality.

        uint256 afterSum = c.balances(depositor) + c.balances(address(attacker));
        uint256 afterBal = address(c).balance;

        // Single assertion that must hold for the correct contract always and is violated by the mutant for some inputs
        assertTrue(afterSum == afterBal);
    }
}

