pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: deposit amount and an initial victim deposit amount
    // We fuzz two amounts so the attacker can reenter and try to steal from another account.
    function testFuzz_property(uint256 attackerDeposit, uint256 victimDeposit) public {
        // keep values in a reasonable wide domain but not zero for attackerDeposit
        attackerDeposit = bound(attackerDeposit, 1, 1 ether);
        victimDeposit = bound(victimDeposit, 0, 1 ether);

        // deploy attacker helper which will reenter in its receive() to call withdraw again
        Attacker attacker = new Attacker(address(c));

        // fund attacker and a victim externally
        vm.deal(address(attacker), attackerDeposit);
        address victim = address(0xBEEF);
        vm.deal(victim, victimDeposit);

        // victim deposits (if any)
        if (victimDeposit > 0) {
            vm.prank(victim);
            // deposit to balances via fallback payable
            (bool ok,) = address(c).call{value: victimDeposit}("");
            require(ok);
        }

        // attacker deposits then triggers withdraw which will attempt reentrancy
        vm.prank(address(attacker));
        // attacker will forward the deposit as part of its attack flow
        attacker.attack{value: attackerDeposit}();

        // The reference contract with the lock guarantees that after the attacker's withdraw call completes,
        // the attacker's recorded balance is zero. The mutant that removed the lock can leave it nonzero.
        assertTrue(c.balances(address(attacker)) == 0);
    }
}

// Minimal reentrant attacker: on receiving ether (during withdraw), it will call withdraw again
contract Attacker {
    address immutable target;
    bool public entered;
    constructor(address _t) payable { target = _t; }

    // entry point used by the test to deposit and start withdraw
    function attack() external payable {
        // deposit by sending to fallback
        (bool ok,) = target.call{value: msg.value}("");
        require(ok);
        // then call withdraw to trigger transfer back into this contract
        (ok,) = target.call(abi.encodeWithSignature("withdraw()"));
        require(ok);
    }

    // Receive called when C.send/call transfers ether to this contract during withdraw
    receive() external payable {
        if (!entered) {
            entered = true;
            // reenter withdraw during the same call flow
            // ignore success to mimic an attacker intent on reentrancy
            (bool,) = target.call(abi.encodeWithSignature("withdraw()"));
        }
    }
}

