pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameters: attacker initial deposit amount and a boolean that if true uses the Attacker helper
    function testFuzz_property(uint256 depositAmount, bool useAttacker) public {
        vm.assume(depositAmount > 0);
        // bound deposit to reasonable size to avoid overflow in test environment
        depositAmount = bound(depositAmount, 1, 1 ether);

        // deploy a helper attacker contract which will reenter during withdraw if used
        Attacker attacker = new Attacker(address(c));

        // fund attacker so it can deposit
        vm.deal(address(attacker), depositAmount);

        // attacker deposits by calling fallback (send Ether)
        attacker.deposit{value: depositAmount}();

        // now attempt to withdraw: if useAttacker is true, attacker will reenter during withdraw
        bool ok;
        if (useAttacker) {
            // attacker calls withdraw on C which may reenter via its fallback/receive
            ok = attacker.tryWithdraw();
        } else {
            // normal EOA caller: make an EOA address and have it deposit and withdraw
            address eoa = address(uint160(uint256(keccak256(abi.encodePacked(block.timestamp, depositAmount)))));
            vm.deal(eoa, depositAmount);
            // EOA deposit
            vm.prank(eoa);
            (bool sent, ) = address(c).call{value: depositAmount}("");
            require(sent);
            // EOA withdraw
            vm.prank(eoa);
            try c.withdraw() {
                ok = true;
            } catch {
                ok = false;
            }
        }

        // Exactly one assertion: in the correct contract, after a caller (attacker or EOA) deposits then calls withdraw,
        // the recorded balance for that caller must be zero. The buggy mutant that removes the reentrancy lock
        // can leave balances(attacker) != 0 for some inputs (found when useAttacker == true).
        if (useAttacker) {
            // read via public getter
            assertTrue(c.balances(address(attacker)) == 0);
        } else {
            // for the EOA case compute the same derived address and assert its recorded balance is zero
            address eoa = address(uint160(uint256(keccak256(abi.encodePacked(block.timestamp, depositAmount)))));
            assertTrue(c.balances(eoa) == 0);
        }
    }
}

