pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz parameters: deposit amount and an arbitrary attacker address (the fuzzer provides both)
    function testFuzz_property(uint128 amount, address attacker) public {
        // keep amount within reasonable bounds but wide enough
        uint256 amt = bound(amount, 1, 1 ether);
        vm.deal(attacker, amt);

        // deploy an attacker contract that will re-enter c.withdraw during its receive()
        Attacker a = new Attacker(c);

        // fund attacker with amt and deposit into c by sending Ether to c via the attacker's helper
        vm.prank(attacker);
        // forward deposit through attacker so c sees msg.sender as attacker
        (bool sent, ) = address(a).call{value: amt}("");
        require(sent);

        // ensure attacker contract has the deposited balance recorded in c
        // now perform withdraw from attacker (attacker's receive will re-enter)
        vm.prank(attacker);
        a.startWithdraw();

        // The universal property: after withdraw completes, correct contract leaves recorded balance 0
        // We assert that c.balances(attacker) == 0. This holds for the reference but the mutant (no lock)
        // can be re-entered and leave a non-zero recorded balance for some inputs.
        assertTrue(c.balances(attacker) == 0);
    }
}

// Minimal re-entrant attacker: on receiving funds, it attempts to call c.withdraw() again
contract Attacker {
    C public c;
    address public owner;
    bool public entered;

    constructor(C _c) payable {
        c = _c;
        owner = msg.sender;
        entered = false;
    }

    // when this contract receives funds (from deposit), it will not re-enter.
    // During withdraw it will re-enter once via receive()
    receive() external payable {
        // re-enter only once to simulate reentrancy
        if (!entered) {
            entered = true;
            // call withdraw on target contract, msg.sender will be this contract
            // use low-level call to propagate any revert
            (bool ok, ) = address(c).call(abi.encodeWithSignature("withdraw()"));
            // ignore ok here
            ok;
        }
    }

    // helper to deposit: fallback will forward ether to this contract enabling deposit via call
    fallback() external payable {}

    // helper called by test to initiate withdraw from this contract
    function startWithdraw() external {
        c.withdraw();
    }
}
